mapper.select:
SELECT
a.*,
u.username AS host_name
FROM accommodations a
LEFT JOIN users u ON a.host_id = u.user_id


    a.accommodation_id IS NOT NULL



        AND a.sido_code = #{sidoCode}


        AND a.gugun_code = #{gugunCode}


        AND a.status = #{status}




        AND a.accommodation_type = #{accommodationType}




        AND EXISTS (
        SELECT 1 FROM rooms r
        WHERE r.accommodation_id = a.accommodation_id

            AND r.price BETWEEN #{minPrice} AND #{maxPrice}


            AND r.price >= #{minPrice}


            AND r.price <= #{maxPrice}

        )




        AND EXISTS (
        SELECT 1
        FROM rooms r
        WHERE r.accommodation_id = a.accommodation_id
        AND r.capacity >= #{guestCount}
        )





    ORDER BY

        a.min_price ASC
        a.min_price DESC
        a.name ASC
        a.created_at DESC

SELECT a.*, u.username as host_name
FROM accommodations a
JOIN accommodations base ON a.sido_code = base.sido_code AND a.gugun_code = base.gugun_code
LEFT JOIN users u ON a.host_id = u.user_id
WHERE base.accommodation_id = #{accommodationId}
AND a.accommodation_id IS NOT NULL
AND a.accommodation_id != #{accommodationId}
AND a.status = 'ACTIVE'
ORDER BY RAND()
LIMIT #{limit}
